import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router';

function UpdateItem() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    itemId: '',
    itemName: '',
    itemCategory: '',
    itemQty: '',
    itemDetails: '',
    itemImage: null
  });

  useEffect(() => {
    const fetchItem = async () => {
      try {
        const response = await axios.get(`http://localhost:8080/inventory/${id}`);
        const itemData = response.data;
        setFormData({
          itemId: itemData.itemId || '',
          itemName: itemData.itemName || '',
          itemCategory: itemData.itemCategory || '',
          itemQty: itemData.itemQty || '',
          itemDetails: itemData.itemDetails || '',
          itemImage: null
        });
      } catch (err) {
        console.error("Error fetching item:", err);
      }
    };

    fetchItem();
  }, [id]);

  const onInputChange = (e) => {
    const { name, value, files } = e.target;
    setFormData({
      ...formData,
      [name]: files ? files[0] : value
    });
  }

  const onSubmit = async (e) => {
    e.preventDefault();
    const data = new FormData();
    data.append("itemDetails", JSON.stringify({
      itemId: formData.itemId,
      itemName: formData.itemName,
      itemCategory: formData.itemCategory,
      itemQty: formData.itemQty,
      itemDetails: formData.itemDetails
    }));
    
    if (formData.itemImage) {
      data.append("file", formData.itemImage);
    }

    try {
      await axios.put(`http://localhost:8080/inventory/${id}`, data);
      alert("Item updated successfully!")
      window.location.href = "/allitems";
    } catch (err) {
      console.error("Error updating item:", err);
      alert("Error updating item");
    }
  };

  // Styles
  const containerStyle = {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 50%, #f093fb 100%)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '40px 20px'
  };

  const formContainerStyle = {
    backgroundColor: 'white',
    borderRadius: '20px',
    padding: '40px',
    boxShadow: '0 10px 40px rgba(0, 0, 0, 0.3)',
    maxWidth: '600px',
    width: '100%'
  };

  const titleStyle = {
    fontSize: '2.5rem',
    fontWeight: 'bold',
    color: '#764ba2',
    marginBottom: '30px',
    textAlign: 'center'
  };

  const labelStyle = {
    fontSize: '1.1rem',
    fontWeight: '600',
    color: '#333',
    marginBottom: '8px',
    display: 'block'
  };

  const inputStyle = {
    width: '100%',
    padding: '12px 15px',
    fontSize: '1rem',
    border: '2px solid #e0e0e0',
    borderRadius: '10px',
    marginBottom: '20px',
    boxSizing: 'border-box',
    transition: 'border-color 0.3s ease'
  };

  const textareaStyle = {
    ...inputStyle,
    minHeight: '100px',
    resize: 'vertical',
    fontFamily: 'inherit'
  };

  const selectStyle = {
    ...inputStyle,
    cursor: 'pointer'
  };

  const buttonStyle = {
    width: '100%',
    backgroundColor: '#764ba2',
    color: 'white',
    fontWeight: 'bold',
    fontSize: '1.2rem',
    padding: '15px',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    marginTop: '10px',
    transition: 'all 0.3s ease',
    boxShadow: '0 4px 15px rgba(118, 75, 162, 0.3)'
  };

  const backButtonStyle = {
    display: 'inline-block',
    color: '#764ba2',
    textDecoration: 'none',
    fontSize: '1rem',
    fontWeight: '600',
    marginBottom: '20px',
    cursor: 'pointer',
    transition: 'color 0.3s ease'
  };

  return (
    <div style={containerStyle}>
      <div style={formContainerStyle}>
        <span 
          style={backButtonStyle}
          onClick={() => navigate('/allitems')}
          onMouseOver={(e) => e.target.style.color = '#667eea'}
          onMouseOut={(e) => e.target.style.color = '#764ba2'}
        >
          ← Back to All Items
        </span>

        <h1 style={titleStyle}>✏️ Update Item</h1>

        <form onSubmit={onSubmit}>
          {/* Item ID */}
          <label htmlFor="itemId" style={labelStyle}>Item ID:</label>
          <input
            type="text"
            id="itemId"
            name="itemId"
            value={formData.itemId}
            onChange={onInputChange}
            style={inputStyle}
            onFocus={(e) => e.target.style.borderColor = '#764ba2'}
            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
            required
          />

          {/* Item Name */}
          <label htmlFor="itemName" style={labelStyle}>Item Name:</label>
          <input
            type="text"
            id="itemName"
            name="itemName"
            value={formData.itemName}
            onChange={onInputChange}
            style={inputStyle}
            onFocus={(e) => e.target.style.borderColor = '#764ba2'}
            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
            required
          />

          {/* Item Category */}
          <label htmlFor="itemCategory" style={labelStyle}>Item Category:</label>
          <select
            id="itemCategory"
            name="itemCategory"
            value={formData.itemCategory}
            onChange={onInputChange}
            style={selectStyle}
            onFocus={(e) => e.target.style.borderColor = '#764ba2'}
            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
            required
          >
            <option value="" disabled>Select Item Category</option>
            <option value="Apparel & Fashion">Apparel & Fashion</option>
            <option value="Electronics & Gadgets">Electronics & Gadgets</option>
            <option value="Health & Beauty">Health & Beauty</option>
            <option value="Food & Dining">Food & Dining</option>
            <option value="Home & Furniture">Home & Furniture</option>
          </select>

          {/* Item Quantity */}
          <label htmlFor="itemQty" style={labelStyle}>Item Quantity:</label>
          <input
            type="number"
            id="itemQty"
            name="itemQty"
            value={formData.itemQty}
            onChange={onInputChange}
            style={inputStyle}
            onFocus={(e) => e.target.style.borderColor = '#764ba2'}
            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
            required
          />

          {/* Item Details */}
          <label htmlFor="itemDetails" style={labelStyle}>Item Details:</label>
          <textarea
            id="itemDetails"
            name="itemDetails"
            value={formData.itemDetails}
            onChange={onInputChange}
            style={textareaStyle}
            onFocus={(e) => e.target.style.borderColor = '#764ba2'}
            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
            required
          />

          {/* Item Image */}
          <label htmlFor="itemImage" style={labelStyle}>Item Image:</label>
          <input
            type="file"
            id="itemImage"
            name="itemImage"
            onChange={onInputChange}
            style={inputStyle}
            accept="image/*"
          />
          <small style={{ color: '#666', display: 'block', marginTop: '-15px', marginBottom: '15px' }}>
            Leave empty to keep current image
          </small>

          {/* Submit Button */}
          <button 
            type="submit" 
            style={buttonStyle}
            onMouseOver={(e) => {
              e.target.style.backgroundColor = '#667eea';
              e.target.style.transform = 'translateY(-2px)';
              e.target.style.boxShadow = '0 6px 20px rgba(118, 75, 162, 0.4)';
            }}
            onMouseOut={(e) => {
              e.target.style.backgroundColor = '#764ba2';
              e.target.style.transform = 'translateY(0)';
              e.target.style.boxShadow = '0 4px 15px rgba(118, 75, 162, 0.3)';
            }}
          >
            Update Item
          </button>
        </form>
      </div>
    </div>
  );
}

export default UpdateItem;
